using System.ComponentModel.DataAnnotations;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Sales;
[Authorize]public sealed class CreateModel(MediStockDbContext db):PageModel{[BindProperty]public SaleInput Input{get;set;}=new();public IReadOnlyList<SelectListItem>Medicines{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult>OnPostAsync(CancellationToken ct){await Load(ct);if(Input.Quantity<1)ModelState.AddModelError("Input.Quantity","Enter at least one unit.");if(!ModelState.IsValid)return Page();var today=DateTime.UtcNow.Date;var batches=await db.StockBatches.Include(x=>x.Medicine).Where(x=>x.MedicineId==Input.MedicineId&&x.Quantity>0&&x.ExpiryDate>=today&&x.Medicine.IsActive).OrderBy(x=>x.ExpiryDate).ThenBy(x=>x.Id).ToListAsync(ct);var remaining=Input.Quantity;if(batches.Count==0){ModelState.AddModelError(string.Empty,"No available non-expired stock exists for this medicine.");return Page();}await using var transaction=await db.Database.BeginTransactionAsync(ct);try{var sale=new Sale{InvoiceNumber=$"INV-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}",SoldAtUtc=DateTime.UtcNow,PaymentMethod=Input.PaymentMethod,Status="Completed"};decimal total=0;foreach(var batch in batches){if(remaining<=0)break;var take=Math.Min(remaining,batch.Quantity);var unit=batch.Medicine.SellingPrice;var line=take*unit;sale.Items.Add(new SaleItem{MedicineId=batch.MedicineId,StockBatchId=batch.Id,Quantity=take,UnitPrice=unit,LineTotal=line});batch.Quantity-=take;remaining-=take;total+=line;}if(remaining>0){await transaction.RollbackAsync(ct);ModelState.AddModelError(string.Empty,"Insufficient stock for this quantity.");return Page();}sale.TotalAmount=total;db.Sales.Add(sale);await db.SaveChangesAsync(ct);await transaction.CommitAsync(ct);TempData["StatusMessage"]="Sale completed.";return RedirectToPage("/Invoices/Details",new{id=sale.Id});}catch(DbUpdateException){await transaction.RollbackAsync(ct);ModelState.AddModelError(string.Empty,"The sale could not be completed.");return Page();}}private async Task Load(CancellationToken ct){var today=DateTime.UtcNow.Date;var ids=await db.StockBatches.AsNoTracking().Where(x=>x.Quantity>0&&x.ExpiryDate>=today).Select(x=>x.MedicineId).Distinct().ToListAsync(ct);Medicines=await db.Medicines.AsNoTracking().Where(x=>ids.Contains(x.Id)&&x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(ct);}}
public sealed class SaleInput{[Required]public int MedicineId{get;set;}[Range(1,1000000)]public int Quantity{get;set;}[Required]public string PaymentMethod{get;set;}="Cash";}
